import subprocess,base64,pathlib,json,datetime
P=pathlib.Path(__file__).resolve().parent
script=r'''$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$d='C:\ProgramData\Enclave\staging\host-services-hs2-20261021-r3';$s=Join-Path $d 'enclave-host-services-hs2-windows';$principal=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());if(!$principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Existing SSH session is not elevated; no install attempted'};$os=Get-CimInstance Win32_OperatingSystem;$free=[math]::Floor($os.FreePhysicalMemory/1024);if($free -lt 17920){throw 'RAM headroom below required'};$disk=Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'";$diskMiB=[math]::Floor($disk.FreeSpace/1MB);if($diskMiB -lt 16384){throw 'Disk headroom below required'};Set-Location -LiteralPath $s;Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force;
& .\windows\install.ps1 -NodeExe 'C:\Program Files\nodejs\node.exe' -ListenersFile (Join-Path $s 'listeners.txt') *> (Join-Path $d 'install.log');if($LASTEXITCODE -ne 0){throw 'Installer refused; inspect receipt and roll back its additions'};
$t=Get-ScheduledTask -TaskPath '\Enclave\' -TaskName 'enclave-host-services-hs2';if($t.State -ne 'Ready' -or @($t.Triggers).Count -ne 0){throw 'Unexpected task state/trigger'};$receipt='C:\ProgramData\Enclave\host-services\hs2\config\install-receipt.txt';if(@(Get-Content -LiteralPath $receipt)[-1] -ne 'complete'){throw 'Receipt incomplete'};$files=0;foreach($l in Get-Content -LiteralPath $receipt){if($l -match '^file ([0-9a-f]{64}) (.+)$'){if((Get-FileHash -LiteralPath $Matches[2] -Algorithm SHA256).Hash.ToLower() -ne $Matches[1]){throw 'Installed hash mismatch'};$files++}};Write-Output ([IO.File]::ReadAllText((Join-Path $d 'install.log')));'RESULT '+(@{status='INSTALLED_NOT_STARTED';task=[string]$t.TaskName;state=[string]$t.State;triggers=[int]@($t.Triggers).Count;verifiedFiles=[int]$files;receipt=[string]$receipt;freeDiskMiB=[int]$diskMiB;freeMemoryMiB=[int]$free;at=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json -Compress)
'''
watch=r'''$ownerPid=$PID;$watchCode='$p=[Diagnostics.Process]::GetProcessById('+[string]$ownerPid+');$p.WaitForExit(120000)|Out-Null;if(!$p.HasExited){$p.Kill()}';$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($watchCode));$watcher=Start-Process -FilePath powershell.exe -ArgumentList @('-NoProfile','-NonInteractive','-EncodedCommand',$encoded) -WindowStyle Hidden -PassThru;try {'''
r=subprocess.run(['ssh','-o','BatchMode=yes','-o','ConnectTimeout=15','minipc','powershell','-NoProfile','-NonInteractive','-EncodedCommand',base64.b64encode((watch+script+'} finally {if(!$watcher.HasExited){$watcher.Kill()}}').encode('utf-16le')).decode()],capture_output=True,text=True,timeout=135)
(P/'host-services-install.log').write_text(r.stdout+r.stderr);print(r.stdout[-8000:]);print(r.stderr[-2000:]);assert r.returncode==0,r.returncode
line=next(x[7:] for x in r.stdout.splitlines() if x.startswith('RESULT '));d=json.loads(line);(P/'host-services-install-result.json').write_text(json.dumps(d,indent=2)+'\n')
